<script>
 let {enquiries=[],preview=false}=$props();
 const date=value=>new Intl.DateTimeFormat('en-ZW',{dateStyle:'medium',timeStyle:'short',timeZone:'Africa/Harare'}).format(new Date(value));
</script>
<section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">PUBLIC WEBSITE</span><h2>Website enquiries</h2></div><span class="admin-status">{enquiries.filter(e=>e.status==='new').length} new</span></div><p class="admin-help">Messages are saved privately here. Email notifications depend on the configured delivery service; enquiries remain available if email fails.</p>
 {#each enquiries as enquiry}<details class="enquiry"><summary><div><strong>{enquiry.name}</strong><span>{enquiry.enquiry} · {date(enquiry.created_at)} CAT</span></div><span class="admin-status" class:good={enquiry.status==='resolved'}>{enquiry.status}</span></summary><div class="enquiry-body"><dl><div><dt>Email</dt><dd><a href={'mailto:'+enquiry.email}>{enquiry.email}</a></dd></div>{#if enquiry.phone}<div><dt>Phone</dt><dd>{enquiry.phone}</dd></div>{/if}{#if enquiry.organisation}<div><dt>Organisation</dt><dd>{enquiry.organisation}</dd></div>{/if}</dl><p class="enquiry-message">{enquiry.message}</p><p class="admin-help">Email notification: {enquiry.notification_status==='sent'?'Accepted by delivery service':enquiry.notification_status==='not_configured'?'Mail service needs configuration':enquiry.notification_status}</p><div class="enquiry-actions"><form method="POST"><input type="hidden" name="operation" value="contact.status"/><input type="hidden" name="enquiry_id" value={enquiry.id}/><label>Enquiry status<select name="status" value={enquiry.status}><option value="new">New</option><option value="reviewed">Reviewed</option><option value="resolved">Resolved</option></select></label><button class="admin-button secondary" disabled={preview}>Update status</button></form>{#if !enquiry.notified_at}<form method="POST"><input type="hidden" name="operation" value="contact.notify"/><input type="hidden" name="enquiry_id" value={enquiry.id}/><button class="admin-button secondary" disabled={preview}>Retry email notification</button></form>{/if}</div></div></details>{/each}
 {#if !enquiries.length}<div class="admin-empty">No website enquiries yet.</div>{/if}
</section>
<style>
 .enquiry{border-top:1px solid #d9e2d1;padding:18px 0}.enquiry summary{display:flex;align-items:center;justify-content:space-between;gap:16px;cursor:pointer;list-style:revert}.enquiry summary strong{display:block;font-size:14px}.enquiry summary div>span{display:block;font-size:11px;color:#61725d;margin-top:6px;line-height:1.8}.enquiry-body{padding-top:20px}dl{display:grid;gap:12px;font-size:12px}dt{color:#61725d}dd{margin:4px 0 0;overflow-wrap:anywhere}.enquiry-message{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;line-height:1.85;background:#f0f4ea;padding:18px;border-radius:8px;margin:18px 0}.enquiry-actions{display:flex;gap:16px;flex-wrap:wrap;align-items:flex-end}.enquiry-actions form{display:flex;align-items:flex-end;gap:12px}.enquiry-actions label{display:grid;gap:6px;font-size:11px}@media(max-width:540px){.enquiry-actions form{flex-wrap:wrap}}
</style>
